static const wchar_t* PIPE_NAME=L"\\\\.\\pipe\\TokenSaver.Phone02.MsixPoA";
static std::wstring SidString(PSID sid){if(!sid||!IsValidSid(sid))return L"UNAVAILABLE";LPWSTR p=nullptr;if(!ConvertSidToStringSidW(sid,&p))return L"UNAVAILABLE";std::wstring s=p;LocalFree(p);return s;}
static std::wstring GetSid(HANDLE t,TOKEN_INFORMATION_CLASS c){DWORD n=0;GetTokenInformation(t,c,nullptr,0,&n);if(!n)return L"UNAVAILABLE";std::vector<BYTE>b(n);if(!GetTokenInformation(t,c,b.data(),n,&n))return L"UNAVAILABLE";PSID sid=c==TokenUser?reinterpret_cast<TOKEN_USER*>(b.data())->User.Sid:reinterpret_cast<TOKEN_APPCONTAINER_INFORMATION*>(b.data())->TokenAppContainer;return SidString(sid);}
static int Client(){HANDLE h=CreateFileW(PIPE_NAME,GENERIC_READ|GENERIC_WRITE,0,nullptr,OPEN_EXISTING,0,nullptr);if(h==INVALID_HANDLE_VALUE){wprintf(L"CLIENT_PIPE_FAIL=%lu\n",GetLastError());return 2;}const char*m="MSIX_TEST_CLIENT_HELLO";DWORD n=0;BOOL ok=WriteFile(h,m,(DWORD)strlen(m),&n,nullptr);wprintf(L"CLIENT_SENT=%lu\n",n);CloseHandle(h);return ok?0:3;}
static int Supervisor(){PSECURITY_DESCRIPTOR sd=nullptr;if(!ConvertStringSecurityDescriptorToSecurityDescriptorW(L"D:P(A;;GA;;;AU)",SDDL_REVISION_1,&sd,nullptr)){wprintf(L"SDDL_FAIL=%lu\n",GetLastError());return 4;}SECURITY_ATTRIBUTES sa{sizeof(sa),sd,FALSE};HANDLE p=CreateNamedPipeW(PIPE_NAME,PIPE_ACCESS_DUPLEX,PIPE_TYPE_MESSAGE|PIPE_READMODE_MESSAGE|PIPE_WAIT|PIPE_REJECT_REMOTE_CLIENTS,1,4096,4096,10000,&sa);LocalFree(sd);if(p==INVALID_HANDLE_VALUE){wprintf(L"PIPE_FAIL=%lu\n",GetLastError());return 5;}wprintf(L"SUPERVISOR_READY\n");BOOL c=ConnectNamedPipe(p,nullptr)?TRUE:(GetLastError()==ERROR_PIPE_CONNECTED);if(!c){wprintf(L"PIPE_CONNECT_FAIL=%lu\n",GetLastError());CloseHandle(p);return 6;}char msg[256]{};DWORD got=0;BOOL rd=ReadFile(p,msg,sizeof(msg)-1,&got,nullptr);BOOL imp=rd&&ImpersonateNamedPipeClient(p);HANDLE t=nullptr;BOOL opened=imp&&OpenThreadToken(GetCurrentThread(),TOKEN_QUERY,TRUE,&t);BYTE app=0;DWORD n=0;if(opened)GetTokenInformation(t,TokenIsAppContainer,&app,sizeof(app),&n);std::wstring user=opened?GetSid(t,TokenUser):L"UNAVAILABLE";std::wstring ac=opened?GetSid(t,TokenAppContainerSid):L"UNAVAILABLE";if(opened)CloseHandle(t);if(imp)RevertToSelf();wprintf(L"SUPERVISOR_CLIENT_BYTES=%lu READ=%u IMPERSONATE=%u TOKEN_OPEN=%u\n",got,rd,imp,opened);wprintf(L"TOKEN_USER_SID=%s\nTOKEN_IS_APPCONTAINER=%u\nTOKEN_APPCONTAINER_SID=%s\n",user.c_str(),app?1:0,ac.c_str());wprintf(L"CLIENT_MESSAGE=%S\n",msg);FlushFileBuffers(p);DisconnectNamedPipe(p);CloseHandle(p);return opened?0:7;}
int wmain(int argc,wchar_t**argv){if(argc>1&&wcscmp(argv[1],L"--supervisor")==0)return Supervisor();return Client();}
